def depth(v):
    m,x=v
    children=x if m==4 else ([t for pair in x for t in pair] if m==5 else ([x[1]] if m==6 else []))
    return 0 if not children else 1+max(map(depth,children))

def compare():
    values,data=corpus()
    payload='\n'.join(b.hex() for b in data)+'\n'
    t=time.monotonic()
    p=subprocess.run([str(ROOT/'target-acceptance/debug/sk-cbor-acceptance')],input=payload,env=ENV,cwd=ROOT,stdout=subprocess.PIPE,stderr=subprocess.PIPE,text=True,timeout=60)
    assert p.returncode==0,(p.returncode,portable(p.stderr))
    lines=p.stdout.splitlines(); assert len(lines)==len(data)
    deviations=[]; accepted=0; rejected=0
    for raw,actual in zip(data,lines):
        try:
            v=parse(raw)
            should=not representable(v) and depth(v)<=127 and encode(v)==raw
        except (Invalid,UnicodeDecodeError,ValueError): should=False
        if actual.startswith('OK '):
            accepted+=1
            if not should or actual.split(' ',2)[1]!=raw.hex() or (should and json.loads(actual.split(' ',2)[2])!=structure(v)): deviations.append(dict(hex=raw.hex(),expected='error' if not should else raw.hex(),actual=actual))
        else:
            rejected+=1
            if should: deviations.append(dict(hex=raw.hex(),expected=raw.hex(),actual=actual))
    summary=dict(provenance=H,seed=8949,generated_values=len(values),unique_inputs=len(data),accepted=accepted,rejected=rejected,deviations=deviations,wall_seconds=time.monotonic()-t,corpus_sha256=hashlib.sha256(payload.encode()).hexdigest(),comparison='Acceptance/rejection for every input; exact decode→encode bytes and independently decoded structural values for every accepted input.',structurally_compared=accepted,limits='Default public read/write on the native target. Exhaustive length 0..2; deterministic generated values, near-valid variants and fixed-seed bytes. No split-stream API exists; all truncation positions for short examples are exercised.')
    (E/'comparison.json').write_text(json.dumps(summary,indent=2)+'\n')
    assert not deviations, f'{len(deviations)} model disagreements; see comparison.json'
    print(f'Reference comparison: {len(data)} inputs, {accepted} accepted, {rejected} rejected; no disagreement.',flush=True)

